<script setup>
import {ref,shallowRef,onBeforeUnmount,computed} from 'vue';
import {Button,Field,Radio,RadioGroup,Cell,CellGroup,Checkbox,Popup,Picker,Dialog,Uploader,showImagePreview} from 'vant';
import 'vant/es/button/style';import 'vant/es/field/style';import 'vant/es/radio/style';import 'vant/es/radio-group/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';import 'vant/es/checkbox/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/dialog/style';
import 'vant/es/uploader/style';import 'vant/es/image-preview/style';
import StudentPhotoReview from './StudentPhotoReview.vue';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=shallowRef(controller.snapshot()),a=controller.actions;
const unsubscribe=controller.subscribe(value=>m.value=value);onBeforeUnmount(unsubscribe);
const writers=ref({}),reviews=ref({}),picker=ref(''),restart=ref(false);
const columns=computed(()=>picker.value==='unit'?[{text:'全部单元',value:'all'},...m.value.units.map(u=>({text:u.term+' · '+u.title,value:u.id}))]:[{text:'全部来源',value:'all'},{text:'原有错题资料（53条）',value:'1025141010'},{text:'期中复习卷（23题）',value:'midterm-20261029'}]);
function choose({selectedValues}){a.filter(picker.value,selectedValues[0]);picker.value='';}
const verdict=v=>({correct:'正确',partial:'部分正确',incorrect:'需要订正',unanswered:'未作答',review:'待人工核对'})[v]||v;
const geometry=q=>{if(!q.geometryHtml)return [];const d=new DOMParser().parseFromString(q.geometryHtml,'text/html');return [...d.querySelectorAll('li')].map(li=>({href:li.querySelector('a')?.getAttribute('href'),title:li.querySelector('a')?.textContent,note:li.querySelector('p')?.textContent}));};
const originals=computed(()=>{const g=m.value.grade,q=m.value.review?.question,p=m.value.review?.paper;if(!g)return [];const pages=g.result.answerPages||[];return pages.length?pages.map((image,i)=>({image,page:i+1})):g.kind==='initial'?(g.result.answerRegions?.length?g.result.answerRegions:q.regions||[]).map(r=>({...r,image:p.pages?.find(p=>p.page===r.page)?.image})).filter(r=>r.image):[];});
</script>
<template><main class="student-math-resources" :data-kind="m.kind"><nav><Button tag="a" :href="m.backHref" icon="arrow-left">{{m.kind==='paper'?'我的试卷':'返回单元'}}</Button></nav><header><p class="eyebrow">{{m.kind==='paper'?'我的试卷 / 同难度检测':'数学 · 单元错题'}}</p><h1 v-if="m.kind==='paper'">{{m.title}}</h1><p v-if="m.kind==='paper'">建议用时 100 分钟 · 满分 100 分 · 23 题</p><p v-if="m.kind==='paper'" class="muted">依据原复习卷的题型与考点编写的新题。包含三角形、实数、勾股定理、因式分解与分式；考点范围与原卷一致。</p></header>
 <p role="status" aria-live="polite">{{m.status}}</p>
 <template v-if="m.kind==='paper'"><div class="actions"><Button type="primary" :disabled="m.blocked||m.busy" :loading="m.busy" @click="a.submit">提交核对得分</Button><Button :disabled="m.blocked||m.busy" @click="restart=true">重新考试</Button><span role="timer" aria-label="考试已用时间">已用时 {{m.clock}}</span></div><section v-if="m.submitted" class="report" aria-live="polite"><h2>总分：{{m.pending?'待评分':m.total+' / 100 分'}}</h2><p>客观题 {{m.objective}} 分；解答题仅有效批改计分，需要复核的原稿暂不计分。</p></section>
 <template v-for="(q,index) in m.questions" :key="q.n"><h2 v-if="!index||q.type!==m.questions[index-1].type" class="section-heading">{{q.type==='choice'?'一、选择题（每题3分，共24分）':q.type==='fill'?'二、填空题（每题3分，共21分）':'三、解答题（共55分，请写出过程）'}}</h2><article :id="'question-'+q.n" class="paper-question" :class="{'is-wrong':q.wrong}"><h2>第 {{q.n}} 题 <small>（{{q.points}} 分）</small></h2><div class="math-prose" v-html="q.promptHtml"/><div v-if="q.figureHtml" class="question-figure" v-html="q.figureHtml"/>
  <RadioGroup v-if="q.type==='choice'" :model-value="m.answers[q.n]" :aria-label="'第 '+q.n+' 题答案（单选）'" :disabled="m.blocked||m.busy" @update:model-value="value=>a.answer(q.n,value)"><p class="answer-legend">第 {{q.n}} 题答案（单选）</p><Radio v-for="(option,i) in q.optionsHtml" :key="i" :name="'ABCD'[i]"><span>{{'ABCD'[i]}}. </span><span v-html="option"/></Radio></RadioGroup>
  <Field v-else-if="q.type==='fill'" :model-value="m.answers[q.n]||''" :label="'第 '+q.n+' 题答案'" maxlength="120" placeholder="输入答案" :disabled="m.blocked||m.busy" @update:model-value="value=>a.answer(q.n,value)"/>
  <template v-else><div class="actions"><Uploader accept="image/jpeg,image/png,image/webp" capture="environment" result-type="file" :disabled="m.blocked||m.busy" :after-read="item=>a.upload(q.n,item.file)"><Button :disabled="m.blocked||m.busy">拍照 / 上传答案</Button></Uploader><Button v-if="q.photo" @click="showImagePreview(q.photo.photos)">查看本次照片</Button></div><details v-if="q.uploads?.length"><summary>上传记录（{{q.uploads.length}}）</summary><article v-for="row in q.uploads" :key="row.key"><p>{{new Date(row.at).toLocaleString('zh-CN')}} · {{row.grade?(row.grade.needsReview?'待复核':row.grade.score+' / 100'):'未批改'}}</p><p v-if="row.grade">{{row.grade.feedback}}</p><Button @click="showImagePreview(row.photos)">查看原稿</Button><Button :disabled="m.blocked||m.busy||q.photo?.key===row.key" @click="a.selectPhoto(q.n,row.key)">{{q.photo?.key===row.key?'本次作答':'使用这份照片'}}</Button></article></details><details v-if="m.writing[q.n]?.some(p=>p.some(s=>s.tool==='pen'))"><summary>查看历史原稿（只读）</summary><canvas v-for="(page,i) in m.writing[q.n]" :key="i" :ref="el=>el&&a.paint(el,page)" width="800" height="1000" style="width:100%;height:auto" :aria-label="'历史原稿第'+(i+1)+'页'"/></details></template>
  <section v-if="m.submitted" class="feedback"><template v-if="q.type!=='solution'"><strong>{{q.ok?'正确':m.answers[q.n]?'待订正':'未作答'}} · {{q.ok?q.points:0}}/{{q.points}} 分</strong><p>参考答案：<span v-html="q.answerHtml"/></p><div v-html="q.solutionHtml"/></template><template v-else-if="q.grade"><strong>{{q.grade.needsReview?'需要复核 · 暂不计分':'AI 得分 '+q.score+' / '+q.points+' 分'}}</strong><p>{{q.grade.feedback}}</p><div v-html="q.gradeDetails"/></template></section>
  <section v-if="q.wrong" class="review"><h3>错题讲解与单元知识点</h3><Cell v-for="link in q.links" :key="link.href" :title="link.unit+' · '+link.title" :url="link.href" is-link/><p>{{q.mappingNote}}</p><div class="actions"><Button :loading="q.aiBusy" :disabled="q.aiBusy" @click="a.explain(String(q.n))">AI 解答 · 分析错因</Button><Button v-if="q.aiBusy" @click="a.cancel(String(q.n))">取消解答</Button></div><div v-if="q.ai" class="math-prose" v-html="q.ai"/></section>
 </article></template></template>
 <template v-else><p role="status">共 {{m.questions.length}} 题</p>
 <article v-for="q in m.questions" :key="q.id" :id="q.sourceId?q.id:'q'+q.number" class="paper-question"><p>{{q.sourceLabel||'1025141010.pdf'}} · 第 {{q.page}} 页 · 第 {{q.number}} 题</p><h2>{{q.title}}</h2><p v-if="q.note">{{q.note}}</p><p v-if="q.review">{{q.review}}</p><div class="math-prose" v-html="q.promptHtml"/><div v-if="q.figureHtml" class="question-figure" v-html="q.figureHtml"/><img v-else-if="q.figure" :src="q.figure" :alt="'第'+q.number+'题设图'" loading="lazy"/><p v-if="m.statsReady">累计做错 {{q.wrongCount||0}} 次</p><div class="actions"><Button :aria-expanded="!!reviews[q.id]" @click="reviews[q.id]=!reviews[q.id]">AI 解答与单元知识点</Button><Button :disabled="m.busy" :loading="m.busy&&m.openId===q.id" :aria-expanded="m.openId===q.id&&!!m.reviewController" :icon="m.openId===q.id&&m.review?'cross':undefined" :aria-label="m.openId===q.id&&m.review?'关闭本题作答记录':undefined" @click="a.history(q.id)"><template v-if="m.openId!==q.id||!m.review">拍照上传与记录</template></Button></div><p v-if="q.record.openStatus" role="status" aria-live="polite">{{q.record.openStatus}}</p><section v-if="reviews[q.id]" class="review"><Cell v-for="link in q.links" :key="link.href" :title="link.unit+' · '+link.title" :url="link.href" is-link/><p>{{q.mappingNote}}</p><template v-for="link in geometry(q)" :key="link.href"><Cell :title="link.title" :url="link.href" is-link/><p>{{link.note}}</p></template><Button @click="a.explain(q.id)">AI 解答</Button><Button @click="a.cancel(q.id)">取消解答</Button><p role="status">{{q.record.status}}</p><div class="math-prose" v-html="q.record.text||''"/></section><template v-if="m.openId===q.id&&m.reviewController&&m.review"><section v-if="m.reviewController.snapshot().question?.questionType==='unknown'" class="review"><p>请按原题的大题标题核对题型，只有解答题可提交 AI批改。</p><div class="actions"><Button :disabled="m.busy" @click="a.questionType('choice')">确认是选择题</Button><Button :disabled="m.busy" @click="a.questionType('fill')">确认是填空题</Button><Button :disabled="m.busy" @click="a.questionType('written')">确认是解答题</Button></div></section><StudentPhotoReview :controller="m.reviewController"/></template></article><p v-if="!m.questions.length">没有符合条件的题目。</p></template>
 <Popup :show="!!picker" @update:show="value=>!value&&(picker='')" position="bottom" round><header class="popup-header"><h2>筛选错题</h2><Button icon="cross" aria-label="关闭筛选" @click="picker=''"/></header><Picker :columns="columns" @confirm="choose"><template #cancel><Button icon="cross" aria-label="关闭筛选" @click="picker=''"/></template></Picker></Popup>
 <Dialog v-model:show="restart" title="重新考试" message="将开始新的本设备试卷，当前试卷草稿会被替换。"><template #footer><div class="actions dialog-actions"><Button icon="cross" aria-label="关闭重新考试确认" @click="restart=false"/><Button type="primary" @click="a.restart();restart=false;writers={}">重新考试</Button></div></template></Dialog>
</main></template>
<style scoped>
.student-math-resources{--van-primary-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b;--van-radio-checked-icon-color:#22634b;--van-checkbox-checked-icon-color:#22634b;max-width:1024px;margin:auto;padding:24px clamp(14px,4vw,36px) 72px;color:#25382c;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;overflow-wrap:anywhere}.student-math-resources,.student-math-resources :deep(*){box-sizing:border-box}.student-math-resources header{padding:24px 0 12px}.student-math-resources h1{font-size:clamp(25px,4vw,36px);line-height:1.4}.student-math-resources p{line-height:1.8}.student-math-resources :deep(.van-button){min-height:44px;font:inherit;text-decoration:none}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.paper-question{border-top:1px solid #dce4dc;padding:26px 0}.paper-question h2{font-size:20px;line-height:1.6}.paper-question small{font-size:14px;font-weight:400}.paper-question img{max-width:100%;height:auto}.paper-question.is-wrong>h2,.paper-question.is-wrong>.math-prose{color:#b42318}.math-prose{line-height:1.9;white-space:pre-wrap;min-width:0}.math-prose :deep(.katex-display){overflow-x:auto;overflow-y:hidden;max-width:100%}.question-figure :deep(svg){max-width:100%;height:auto;max-height:340px;display:block;margin:16px auto}.question-figure :deep(text){font:16px sans-serif;fill:currentColor}.student-math-resources :deep(.van-radio){min-height:48px;padding:10px 0;align-items:flex-start}.student-math-resources :deep(.van-radio__label){min-width:0;line-height:1.8}.student-math-resources :deep(.van-field__control){border:0;background:transparent;min-height:0;padding:0;box-shadow:none;font:inherit}.student-math-resources :deep(.van-cell){min-height:52px}.student-math-resources :deep(.van-cell-group--inset){margin:0}.feedback,.report,.review{background:#f2f6f1;padding:16px;margin-top:18px;border-radius:8px;line-height:1.8}.review :deep(.van-cell){background:transparent}.popup-header{display:flex;justify-content:space-between;align-items:center;padding:16px;gap:12px}.popup-header h2{font-size:18px;margin:0}.popup-header :deep(.van-button),.dialog-actions :deep(.van-button:first-child){min-width:44px;height:44px}.history-popup{height:88dvh;overflow:auto;padding:0 18px 36px;color:#25382c}.history-popup img{max-width:100%;height:auto}.history-popup figure{margin:20px 0}.dialog-actions{justify-content:center;padding:6px 12px}.student-math-resources :deep(.van-popup){--van-primary-color:#22634b}
